  ('aphyosemion-australe', 'Aphyosemion australe', 'Aphyosemion australe', 'killifishler', 'fish', 'Orta', 'Barışçıl', 'Lir kuyruklu, renkli bir killi. Yumuşak, hafif asidik ve serin su sever.', '[["Yetişkin boy","5–6 cm"],["Sıcaklık","21–24 °C"],["pH","5.5–7"],["Min. akvaryum","40 L"],["Huy","Barışçıl"],["Beslenme","Etçil"],["Üreme","Bitkilere yumurtlar"],["Köken","Batı Afrika"],["Ömür","3 yıl"]]'::jsonb, array['aphyosemion', 'killi']::text[], false),
